import json
from pathlib import Path

def field(slug,t='string',label=None,**kw):return dict(slug=slug,label=label or slug.replace('_',' ').title(),type=t,**kw)
def select(s,opts):return field(s,'select',validation={'options':opts})
def ref(s,target):return field(s,'reference',validation={'targetCollection':target,'multiple':False})
def repeat(s,fields):return field(s,'repeater',validation={'subFields':fields})
def pt(s):return [{'_type':'block','_key':'p'+str(i),'style':'normal','children':[{'_type':'span','_key':'s'+str(i),'text':p,'marks':[]}],'markDefs':[]} for i,p in enumerate(s.split('\n\n'))]
