def img(i,alt='Illustrative stock photograph; not an actual property offered for sale'):
 return {'$media':{'url':'https://images.unsplash.com/'+photos[i%len(photos)]+'?auto=format&fit=crop&w=1440&q=80','alt':alt,'filename':'northfield-'+str(i%len(photos))+'.jpg'}}
def entry(slug,data,status='published'):return {'id':slug,'slug':slug,'status':status,'data':data}
def block(t,**data):return dict(_type=t,_version=1,_key=t+'-'+str(len(data))+str(len(str(data))),**data)
